def count_axis_squares(H, V, tol=0.125, t=4):
    def covH(y, xa, xb): return any(abs(c-y) <= t and a <= xa+t and b >= xb-t for c, a, b in H)
    def covV(x, ya, yb): return any(abs(c-x) <= t and a <= ya+t and b >= yb-t for c, a, b in V)
    xs = sorted({c for c, _, _ in V}); ys = sorted({c for c, _, _ in H})
    n = 0
    for i, x1 in enumerate(xs):
        for x2 in xs[i+1:]:
            for j, y1 in enumerate(ys):
                for y2 in ys[j+1:]:
                    w, h = x2-x1, y2-y1
                    if abs(w-h)/max(w, h) > tol: continue
                    if covH(y1, x1, x2) and covH(y2, x1, x2) and covV(x1, y1, y2) and covV(x2, y1, y2):
                        n += 1
    return n

